files.content:
.wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.box {
  align-items: stretch;
}

.textarea {
  flex: 1;
  min-width: 0;
  min-height: 88px;
  padding: calc(11px * var(--density)) var(--input-pad-x, calc(14px * var(--density)));
  border: 0;
  outline: none;
  background: transparent;
  resize: vertical;
  font-family: var(--font-body);
  font-size: var(--input-font-size, var(--text-input));
  line-height: 1.55;
  color: var(--ink-body);
  border-radius: inherit;
}

/* Focus is drawn on the whole box (TextInput's .box:focus-within). (0,2,0)
   outranks globals.css's :focus-visible fallback in any load order. */
.textarea:focus,
.textarea:focus-visible {
  outline: none;
}

.textarea::placeholder {
  color: var(--ink-placeholder);
  opacity: 1;
}

.textarea:disabled {
  cursor: not-allowed;
  resize: none;
  color: var(--ink-disabled);
}

.count {
  align-self: flex-end;
  font-size: var(--text-caption);
  font-variant-numeric: tabular-nums;
  color: var(--ink-muted);
}

.countNear {
  color: var(--warning-ink);
  font-weight: 700;
}

"use client";

import type { ComponentPropsWithRef } from "react";
import { cx } from "../_internal/cx";
import { mergeDescribedBy, useField } from "../Field/Field";
import boxStyles from "../TextInput/TextInput.module.css";
import styles from "./Textarea.module.css";

export type TextareaProps = ComponentPropsWithRef<"textarea"> & {
  invalid?: boolean;
  /** Shows "n / max" under the box. Requires maxLength and a controlled value. */
  showCount?: boolean;
};

export function Textarea({
  invalid: invalidProp,
  showCount,
  className,
  id: idProp,
  rows = 4,
  required,
  disabled,
  readOnly,
  maxLength,
  value,
  "aria-describedby": describedByProp,
  ...rest
}: TextareaProps) {
  const field = useField();
  const invalid = invalidProp ?? field?.invalid ?? false;
  const id = idProp ?? field?.id;
  const countId = showCount && maxLength ? `${id}-count` : undefined;
  const length = typeof value === "string" ? value.length : 0;
  const nearLimit = maxLength ? length >= maxLength * 0.9 : false;

  return (
    <div data-slot="textarea" className={styles.wrap}>
      <div
        className={cx(
          boxStyles.box,
          styles.box,
          invalid && boxStyles.invalid,
          disabled && boxStyles.disabled,
          readOnly && boxStyles.readOnly,
        )}
      >
        <textarea
          id={id}
          rows={rows}
          className={cx(styles.textarea, className)}
          aria-invalid={invalid || undefined}
          aria-describedby={mergeDescribedBy(describedByProp, field?.describedBy, countId)}
          required={required ?? field?.required}
          disabled={disabled}
          readOnly={readOnly}
          maxLength={maxLength}
          value={value}
          {...rest}
        />
      </div>
      {countId ? (
        <p id={countId} className={cx(styles.count, nearLimit && styles.countNear)} aria-live="polite">
          {length} / {maxLength}
        </p>
      ) : null}
    </div>
  );
}
